<section class="page-heading"><span class="eyebrow">SELL & LET WITH VEYRA</span><h1><?= e($title) ?></h1><p>Save your details as a draft, add photographs, then submit for a careful review.</p></section><div class="page-main"><form class="panel" method="post" action="/submit"><?= csrf() ?><input type="hidden" name="id" value="<?= e($p['id'] ?? 0) ?>"><span class="eyebrow">01 · THE ESSENTIALS</span><h3>Tell us about your home.</h3><div class="form-grid"><label class="field wide"><span>Property title</span><input name="title" minlength="4" maxlength="190" required value="<?= e($p['title'] ?? '') ?>" placeholder="A considered name for your property"></label><label class="field wide"><span>Description</span><textarea name="description" minlength="20" required><?= e($p['description'] ?? '') ?></textarea></label><label class="field"><span>Purpose</span><select name="purpose"><option value="sale">Sale</option><option value="rent" <?= ($p['purpose'] ?? '')==='rent'?'selected':'' ?>>Rent</option></select></label><label class="field"><span>Property type</span><select name="property_type"><?php foreach ($data['types'] as $t): ?><option <?= ($p['property_type'] ?? '')===$t['name']?'selected':'' ?>><?= e($t['name']) ?></option><?php endforeach ?></select></label><label class="field"><span>Price (USD; monthly for rentals)</span><input type="number" name="price" min="1" step=".01" value="<?= e(isset($p['price_minor'])?$p['price_minor']/100:'') ?>" required></label><label class="field"><span>Bedrooms</span><input type="number" name="bedrooms" min="0" max="100" value="<?= e($p['bedrooms'] ?? 3) ?>" required></label><label class="field"><span>Bathrooms</span><input type="number" name="bathrooms" min="0" max="100" step=".5" value="<?= e($p['bathrooms'] ?? 2) ?>" required></label><label class="field"><span>Floor area</span><input type="number" name="floor_area" min="1" step=".01" value="<?= e($p['floor_area'] ?? '') ?>" required></label><label class="field"><span>Measurement unit</span><select name="area_unit"><option value="sqft">Square feet</option><option value="sqm" <?= ($p['area_unit'] ?? '')==='sqm'?'selected':'' ?>>Square meters</option></select></label></div><span class="eyebrow">02 · A SENSE OF PLACE</span><h3>Location, with privacy in mind.</h3><div class="form-grid"><label class="field wide"><span>Private street address</span><input name="address" required value="<?= e($p['address'] ?? '') ?>"></label><label class="field"><span>City</span><input name="city" required value="<?= e($p['city'] ?? '') ?>"></label><label class="field"><span>Public location disclosure</span><select name="location_privacy"><?php foreach (['approximate'=>'Approximate coordinates; address withheld','private'=>'City only; coordinates withheld','exact'=>'Exact address and coordinates'] as $k=>$v): ?><option value="<?= $k ?>" <?= ($p['location_privacy'] ?? 'approximate')===$k?'selected':'' ?>><?= $v ?></option><?php endforeach ?></select></label><label class="field"><span>Latitude</span><input type="number" name="latitude" step="any" min="-90" max="90" value="<?= e($p['latitude'] ?? 34.09) ?>" required></label><label class="field"><span>Longitude</span><input type="number" name="longitude" step="any" min="-180" max="180" value="<?= e($p['longitude'] ?? -118.41) ?>" required></label></div><span class="eyebrow">03 · THOUGHTFUL DETAILS</span><h3>Amenities & accessibility</h3><div class="check-list"><?php foreach ($data['amenities'] as $a): ?><label><input type="checkbox" name="amenities[]" value="<?= $a['id'] ?>" <?= in_array($a['id'],$data['selected'])?'checked':'' ?>> <?= e($a['name']) ?></label><?php endforeach ?></div><?php require ROOT.'/templates/partials/listing-extras.php'; ?><button class="button">Save draft <?= icon('arrow') ?></button><p class="tiny">All significant edits to published properties return the listing to review.</p></form><?php if ($p): ?><div class="two-column"><div class="panel"><h3>Photographs & floor plans</h3><form method="post" action="/dashboard/action" enctype="multipart/form-data"><?= csrf() ?><input type="hidden" name="action" value="media_upload"><input type="hidden" name="tab" value="listings"><input type="hidden" name="id" value="<?= $p['id'] ?>"><label class="field"><span>File (up to 8 MB)</span><input type="file" name="file" accept="image/jpeg,image/png,image/webp,application/pdf" required></label><div class="form-grid"><label class="field"><span>Kind</span><select name="kind"><option value="photo">Photograph</option><option value="floorplan">Floor plan</option></select></label><label class="field"><span>Display order</span><input type="number" name="sort_order" value="0" min="0"></label></div><button class="button">Upload file</button></form></div><div class="panel"><h3>Ready for review?</h3><p>Your property is currently <b><?= e($p['status']) ?></b>. An administrator reviews submitted listings and assigns an approved agent before publication.</p><form method="post" action="/dashboard/action"><?= csrf() ?><input type="hidden" name="action" value="listing_state"><input type="hidden" name="id" value="<?= $p['id'] ?>"><input type="hidden" name="state" value="submitted"><input type="hidden" name="tab" value="listings"><button class="button">Submit for review <?= icon('arrow') ?></button></form></div></div><?php endif ?></div>
